CREATE TABLE categorias (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fornecedores (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE locais (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE produtos (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, preco DECIMAL(10,2) NOT NULL, quantidade INT UNSIGNED NOT NULL, categoria_id INT NOT NULL, fornecedor_id INT NOT NULL, local_id INT NOT NULL, FOREIGN KEY(categoria_id) REFERENCES categorias(id), FOREIGN KEY(fornecedor_id) REFERENCES fornecedores(id), FOREIGN KEY(local_id) REFERENCES locais(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE historico (id INT AUTO_INCREMENT PRIMARY KEY, tabela VARCHAR(40) NOT NULL, registro_id INT NOT NULL, operacao VARCHAR(20) NOT NULL, antes LONGTEXT NULL, depois LONGTEXT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;